'use strict';
// Only authenticated, owner-scoped file identities enter this workflow.
function previewRequest(item){
 const auth=item?.headers?.authorization,b=item?.body;
 if(typeof auth!=='string'||!/^Bearer [A-Za-z0-9._-]{20,8000}$/.test(auth))return {ok:false,code:'AUTH_REQUIRED'};
 if(!b||typeof b!=='object'||Object.keys(b).some(k=>!['asset_id','asset_revision'].includes(k))||!/^\w{8}-\w{4}-\w{4}-\w{4}-\w{12}$/.test(b.asset_id||'')||typeof b.asset_revision!=='string'||b.asset_revision.length<1||b.asset_revision.length>250)return {ok:false,code:'INVALID_INPUT'};
 return {ok:true,auth,input:{p_asset_id:b.asset_id,p_revision:b.asset_revision}};
}
function previewMetadata(file,context,folders){
 if(context?.ok!==true||file?.id!==context.drive_file_id||file.trashed!==false||file.mimeType!==context.mime_type||String(file.size)!==String(context.size_bytes)||!Array.isArray(file.parents)||!file.parents.some(p=>folders.includes(p)))throw Error('FILE_UNAVAILABLE');
 // Drive can update metadata after an upload; the checksum still binds the bytes.
 const revision=context.asset_revision;
 const unchanged=revision.startsWith('sha256:')?revision.split(':')[1]===file.sha256Checksum:revision.startsWith('md5:')?revision.split(':')[1]===file.md5Checksum:revision==='version:'+file.version;
 if(!unchanged)throw Error('FILE_CHANGED');
 if(typeof file.thumbnailLink!=='string'||!/^https:\/\/lh[3-6]\.googleusercontent\.com\/[A-Za-z0-9_\-=/]+$/.test(file.thumbnailLink)||file.thumbnailLink.length>4000)throw Error('PREVIEW_UNAVAILABLE');
 return {url:file.thumbnailLink};
}
function previewImage(bytes,context){
 if(!bytes||bytes.length<12||bytes.length>2000000)throw Error('PREVIEW_UNAVAILABLE');
 const mime=bytes[0]===255&&bytes[1]===216&&bytes[2]===255?'image/jpeg':bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))?'image/png':bytes.toString('ascii',0,4)==='RIFF'&&bytes.toString('ascii',8,12)==='WEBP'?'image/webp':null;
 if(!mime)throw Error('PREVIEW_UNAVAILABLE');
 return {ok:true,asset_id:context.asset_id,asset_revision:context.asset_revision,media_kind:context.media_kind,mime_type:mime,image_base64:bytes.toString('base64'),can_publish:false};
}

return [{json:previewRequest($input.first().json)}];

'use strict';
const DRIVE_ID=/^[A-Za-z0-9_-]{10,200}$/;
// Drive may not have finished extracting video metadata yet. Missing values
// stay unknown; they must never become zero or a successful media inspection.
function mediaMetadata(f){
 const video=f.mimeType?.startsWith('video/');
 const m=(video?f.videoMediaMetadata:f.imageMediaMetadata)||{};
 const dimension=v=>Number.isInteger(v)&&v>0&&v<=1000000?v:null;
 const duration=video&&typeof m.durationMillis==='string'&&/^\d{1,13}$/.test(m.durationMillis)?Number(m.durationMillis):null;
 return {width_px:dimension(m.width),height_px:dimension(m.height),duration_ms:duration};
}
function verifiedFolders(rows,context){
 const matches=rows.filter(r=>r?.kunde_id);const k=matches.length===1?matches[0]:null;
 const norm=x=>String(x||'').trim().toLowerCase();
 if(context?.ok!==true||!k||k.kunde_id!==context.n8n_kunde_id||norm(k.kunde_email)!==norm(context.kunde_email)||k.zugang_aktiv!==true||!(k.demo_delta_aktiv===true||k.zahlung_bestaetigt===true))throw Error('FOLDER_UNAVAILABLE');
 const folders=[...new Set([k.upload_folder_id,k.processing_folder_id])];
 if(folders.length!==2||folders.some(f=>typeof f!=='string'||!DRIVE_ID.test(f)))throw Error('FOLDER_UNAVAILABLE');
 return {folders,q:"trashed = false and ("+folders.map(f=>"'"+f+"' in parents").join(' or ')+") and (mimeType contains 'image/' or mimeType contains 'video/')"};
}
function accessibleFolders(metadata,context){
 const folders=context?.folders;
 if(!Array.isArray(folders)||folders.length!==2||new Set(folders).size!==2||folders.some(f=>typeof f!=='string'||!DRIVE_ID.test(f))||!Array.isArray(metadata)||metadata.length!==2)throw Error('FOLDER_UNAVAILABLE');
 for(let i=0;i<folders.length;i++){
  const f=metadata[i];
  if(f?.id!==folders[i]||f.mimeType!=='application/vnd.google-apps.folder'||f.trashed!==false||f.capabilities?.canListChildren!==true)throw Error('FOLDER_UNAVAILABLE');
 }
 return context;
}
function catalogFiles(response,folders){
 if(!response||!Array.isArray(response.files)||response.incompleteSearch===true)throw Error('FILE_METADATA_INVALID');
 if(response.nextPageToken||response.files.length>1000)throw Error('FILE_CATALOG_TOO_LARGE');
 const seen=new Set();return response.files.map(f=>{
  if(!DRIVE_ID.test(f.id||'')||seen.has(f.id)||f.trashed===true||!Array.isArray(f.parents)||!f.parents.some(p=>folders.includes(p)))throw Error('FILE_METADATA_INVALID');
  seen.add(f.id);
  if(typeof f.name!=='string'||f.name.length<1||f.name.length>500||/[\u0000-\u001f\u202a-\u202e\u2066-\u2069]/u.test(f.name)||! /^(image|video)\/[A-Za-z0-9.+-]+$/.test(f.mimeType||''))throw Error('FILE_METADATA_INVALID');
  if(!/^\d{1,18}$/.test(f.size||'')||!/^\d{1,30}$/.test(f.version||'')||!Number.isFinite(Date.parse(f.modifiedTime)))throw Error('FILE_METADATA_INVALID');
  const checksum=/^[a-f0-9]{64}$/.test(f.sha256Checksum||'')?'sha256:'+f.sha256Checksum:/^[a-f0-9]{32}$/.test(f.md5Checksum||'')?'md5:'+f.md5Checksum:'version';
  return {drive_file_id:f.id,name:f.name,media_kind:f.mimeType.startsWith('video/')?'video':'image',mime_type:f.mimeType,revision:checksum+':'+f.version,modified_at:new Date(f.modifiedTime).toISOString(),size_bytes:String(f.size),...mediaMetadata(f)};
 });
}

return [{json:verifiedFolders($input.all().map(x=>x.json),$('Eigene Datei prüfen').first().json)}];

'use strict';
const {createHash}=require('crypto');
function editorSourceMetadata(file,context,folders){
 if(context?.ok!==true||file?.id!==context.drive_file_id||file.trashed!==false||file.capabilities?.canDownload!==true||file.mimeType!==context.mime_type||String(file.size)!==String(context.size_bytes)||!Array.isArray(file.parents)||!file.parents.some(p=>folders.includes(p))||!['video/mp4','image/jpeg','image/png','image/webp'].includes(file.mimeType)||!(Number(file.size)>0&&Number(file.size)<=24000000))throw Error('FILE_UNAVAILABLE');
 const revision=context.asset_revision;
 const same=revision.startsWith('sha256:')?revision==='sha256:'+file.sha256Checksum+':'+file.version:revision.startsWith('md5:')?revision==='md5:'+file.md5Checksum+':'+file.version:revision==='version:'+file.version;
 if(!same)throw Error('FILE_CHANGED');
 const sha256=/^[a-f0-9]{64}$/.test(file.sha256Checksum||'')?file.sha256Checksum:null,md5=/^[a-f0-9]{32}$/.test(file.md5Checksum||'')?file.md5Checksum:null;
 if(!sha256&&!md5)throw Error('SOURCE_UNVERIFIED');
 return {sha256,md5,size_bytes:Number(file.size)};
}
function editorSourceBytes(bytes,context,metadata){
 if(!Buffer.isBuffer(bytes)||bytes.length<12||bytes.length>24000000||bytes.length!==metadata.size_bytes)throw Error('SOURCE_UNVERIFIED');
 const sha256=createHash('sha256').update(bytes).digest('hex');
 if(metadata.sha256&&sha256!==metadata.sha256||metadata.md5&&createHash('md5').update(bytes).digest('hex')!==metadata.md5)throw Error('FILE_CHANGED');
 const magic=context.mime_type==='video/mp4'?bytes.toString('ascii',4,8)==='ftyp':context.mime_type==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:context.mime_type==='image/png'?bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):context.mime_type==='image/webp'?bytes.toString('ascii',0,4)==='RIFF'&&bytes.toString('ascii',8,12)==='WEBP':false;
 if(!magic)throw Error('SOURCE_UNVERIFIED');
 return {ok:true,can_publish:false,asset_id:context.asset_id,asset_revision:context.asset_revision,media_kind:context.media_kind,mime_type:context.mime_type,size_bytes:bytes.length,sha256,data_base64:bytes.toString('base64')};
}

return [{json:editorSourceMetadata($input.first().json,$('Eigene Datei prüfen').first().json,$('Ordner prüfen').first().json.folders)}];

